<script src="/js/vivencia-cart.js"></script>
<!-- Inline Vanilla JavaScript Micro-Interactions -->
<script>
    // State management for order request
    const cartState = {};

    function incrementCount(id) {
      const el = document.getElementById(id + '-qty');
      if (el) {
        let val = parseInt(el.innerText, 10);
        el.innerText = val + 1;
      }
    }

    function decrementCount(id) {
      const el = document.getElementById(id + '-qty');
      if (el) {
        let val = parseInt(el.innerText, 10);
        if (val > 1) {
          el.innerText = val - 1;
        }
      }
    }

    function addToOrder(name, price, qtyId) {
      const qtyEl = document.getElementById(qtyId + '-qty');
      const qty = qtyEl ? parseInt(qtyEl.innerText, 10) : 1;

      if (cartState[name]) {
        cartState[name].quantity += qty;
      } else {
        cartState[name] = {
          price: price,
          quantity: qty
        };
      }

      // Reset count back to 1 for quick next add
      if (qtyEl) qtyEl.innerText = '1';

      renderCart();
      vivenciaCartStore.write(cartState);
    }

    function removeCartItem(name) {
      delete cartState[name];
      renderCart();
      vivenciaCartStore.write(cartState);
    }

    function renderCart() {
      const emptyEl = document.getElementById('cart-empty');
      const itemsEl = document.getElementById('cart-items');
      const calcEl = document.getElementById('cart-calculation');
      const submitBtn = document.getElementById('cart-submit-btn');
      const countEl = document.getElementById('cart-item-count');

      const keys = Object.keys(cartState);
      let totalItems = 0;
      let subtotal = 0;

      itemsEl.innerHTML = '';

      if (keys.length === 0) {
        emptyEl.classList.remove('hidden');
        itemsEl.classList.add('hidden');
        calcEl.classList.add('hidden');
        countEl.innerText = '0 items';
        submitBtn.disabled = true;
        submitBtn.className = 'w-full py-space-sm px-space-md rounded-full bg-surface-container-highest text-outline font-label-md text-label-md cursor-not-allowed transition-all flex items-center justify-center gap-space-xs';
        return;
      }

      emptyEl.classList.add('hidden');
      itemsEl.classList.remove('hidden');
      calcEl.classList.remove('hidden');

      keys.forEach(name => {
        const item = cartState[name];
        totalItems += item.quantity;
        const itemTotal = item.price * item.quantity;
        subtotal += itemTotal;

        const row = document.createElement('div');
        row.className = 'flex items-center justify-between p-space-xs rounded bg-surface-container text-body-sm text-body-sm';
        row.innerHTML = `
          <div class="flex flex-col min-w-0 flex-1 mr-2">
            <span class="font-headline-sm text-[14px] text-on-surface truncate">${name}</span>
            <span class="text-on-surface-variant font-label-sm text-label-sm">${item.quantity} × $${item.price}</span>
          </div>
          <div class="flex items-center gap-space-xs shrink-0">
            <span class="font-bold text-primary">$${itemTotal}</span>
            <button onclick="removeCartItem('${name}')" class="text-outline hover:text-error ml-1">
              <span class="material-symbols-outlined text-[18px]">delete</span>
            </button>
          </div>
        `;
        itemsEl.appendChild(row);
      });

      countEl.innerText = totalItems + (totalItems === 1 ? ' item' : ' items');
      const deposit = (subtotal * 0.5);

      document.getElementById('summary-subtotal').innerText = '$' + subtotal.toFixed(2);
      document.getElementById('summary-deposit').innerText = '$' + deposit.toFixed(2);
      document.getElementById('summary-pickup-due').innerText = '$' + deposit.toFixed(2);

      submitBtn.disabled = false;
      submitBtn.className = 'w-full py-space-sm px-space-md rounded-full bg-tertiary-fixed-dim text-on-tertiary-fixed font-label-md text-label-md shadow hover:bg-tertiary-fixed transition-all flex items-center justify-center gap-space-xs cursor-pointer';
    }

    function filterCategory(cat, btn) {
      // Style pills
      const buttons = document.querySelectorAll('.category-btn');
      buttons.forEach(b => {
        b.className = 'category-btn px-space-md py-space-xs rounded-full font-label-md text-label-md transition-all shrink-0 bg-surface-container-high text-on-surface-variant hover:text-primary';
      });
      btn.className = 'category-btn px-space-md py-space-xs rounded-full font-label-md text-label-md transition-all shrink-0 bg-primary text-on-primary shadow-sm';

      // Toggle category groups
      const groups = document.querySelectorAll('.category-group');
      groups.forEach(group => {
        if (cat === 'all' || group.getAttribute('data-category') === cat) {
          group.style.display = 'flex';
        } else {
          group.style.display = 'none';
        }
      });
    }

    function submitOrderModal() {
      const items = vivenciaCartStore.asItems(cartState);
      if (items.length === 0) return;
      const selectedDate = document.getElementById('preorder-date')?.value || '';
      const dateQuery = selectedDate ? '&pickup_date=' + encodeURIComponent(selectedDate) : '';
      window.location.href = '/order?cart=' + encodeURIComponent(JSON.stringify(items)) + dateQuery;
    }

    function closeOrderModal() {
      document.getElementById('order-modal').classList.add('hidden');
    }
  </script>
